func (r *QueryResolver) PlaceAutocomplete(ctx context.Context, input gqlmodel.PlaceAutocompleteInput) (*kernelports.AutocompleteLocationResult, error) {
	authCtx, err := r.RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	return r.AutoCompleteService.GetPlaceDetails(ctx, &kernelports.AutoCompleteRequest{
		TenantInfo:   resolvercore.TenantInfo(authCtx),
		Input:        input.Input,
		SessionToken: gqlscalar.StringValue(input.SessionToken),
	})
}
